package com.ace67.browser;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.content.*;import android.net.Uri;import android.widget.*;import android.webkit.*;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root,tabStrip;EditText address;Button go,add,save;HorizontalScrollView tabScroll;ArrayList<WebView> views=new ArrayList<>();ArrayList<String> savedUrls=new ArrayList<>();int active=-1;int bg=0xff101014,red=0xffff174f,white=Color.WHITE;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(white);b.setTextSize(12);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(red));return b;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);ui();addTab("https://example.com");}
 void ui(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);setContentView(root);
 TextView title=txt("ACE67 BROWSER",21,red);title.setTypeface(null,1);title.setPadding(dp(15),dp(12),dp(15),dp(5));root.addView(title);
 LinearLayout row=new LinearLayout(this);row.setPadding(dp(8),dp(4),dp(8),dp(4));address=new EditText(this);address.setSingleLine(true);address.setTextColor(white);address.setHintTextColor(0xffaaaaaa);address.setHint("https://website.com");address.setText("https://example.com");address.setTextSize(14);row.addView(address,new LinearLayout.LayoutParams(0,dp(46),1));go=btn("GO");row.addView(go,new LinearLayout.LayoutParams(dp(60),dp(46)));root.addView(row);
 go.setOnClickListener(v->navigate(address.getText().toString()));address.setOnEditorActionListener((v,id,e)->{navigate(address.getText().toString());return true;});
 LinearLayout actions=new LinearLayout(this);actions.setPadding(dp(8),0,dp(8),0);add=btn("+ NEW TAB");save=btn("SAVE TABS");actions.addView(add,new LinearLayout.LayoutParams(0,dp(43),1));actions.addView(save,new LinearLayout.LayoutParams(0,dp(43),1));root.addView(actions);add.setOnClickListener(v->addTab(address.getText().toString()));save.setOnClickListener(v->saveTabs());
 tabScroll=new HorizontalScrollView(this);tabScroll.setHorizontalScrollBarEnabled(false);tabStrip=new LinearLayout(this);tabStrip.setPadding(dp(5),dp(4),dp(5),dp(4));tabScroll.addView(tabStrip);root.addView(tabScroll,new LinearLayout.LayoutParams(-1,dp(47)));
 TextView note=txt("ট্যাব বদলাতে উপরের Tab বোতাম চাপুন • বন্ধ করতে long-press",11,0xffaaaaaa);note.setPadding(dp(10),dp(2),dp(10),dp(4));root.addView(note);}
 String norm(String s){s=s.trim();if(s.isEmpty())s="https://example.com";if(!s.matches("(?i)^https?://.*"))s="https://"+s;return s;}
 void addTab(String u){if(views.size()>=50){Toast.makeText(this,"সর্বোচ্চ ৫০টি ট্যাব",0).show();return;}WebView w=new WebView(this);config(w);views.add(w);savedUrls.add(norm(u));switchTab(views.size()-1);w.loadUrl(norm(u));tabs();}
 void config(WebView w){WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setLoadsImagesAutomatically(true);s.setSupportZoom(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);w.setBackgroundColor(Color.WHITE);w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){if(u.startsWith("http://")||u.startsWith("https://"))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){}return true;}});w.setWebChromeClient(new WebChromeClient());}
 void switchTab(int i){if(i<0||i>=views.size())return;if(active>=0){WebView old=views.get(active);if(old.getParent()!=null)((ViewGroup)old.getParent()).removeView(old);}active=i;WebView w=views.get(i);if(w.getParent()!=null)((ViewGroup)w.getParent()).removeView(w);root.addView(w,new LinearLayout.LayoutParams(-1,0,1),root.getChildCount());address.setText(w.getUrl()==null?savedUrls.get(i):w.getUrl());tabs();}
 void navigate(String u){if(active<0){addTab(u);return;}u=norm(u);savedUrls.set(active,u);views.get(active).loadUrl(u);address.setText(u);}
 void tabs(){tabStrip.removeAllViews();for(int i=0;i<views.size();i++){final int n=i;Button b=btn((i==active?"● ":"")+"Tab "+(i+1)+" ×");b.setTextSize(11);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(i==active?red:0xff393943));tabStrip.addView(b,new LinearLayout.LayoutParams(dp(100),dp(37)));b.setOnClickListener(v->switchTab(n));b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setMessage("Tab "+(n+1)+" বন্ধ করবেন?").setPositiveButton("Close",(d,x)->close(n)).setNegativeButton("Cancel",null).show();return true;});}}
 void close(int i){if(views.size()==1){views.get(0).loadUrl("https://example.com");savedUrls.set(0,"https://example.com");switchTab(0);return;}WebView w=views.remove(i);savedUrls.remove(i);if(w.getParent()!=null)((ViewGroup)w.getParent()).removeView(w);w.destroy();int next=Math.max(0,Math.min(active-(i<=active?1:0),views.size()-1));active=-1;switchTab(next);}
 void saveTabs(){StringBuilder s=new StringBuilder();for(int i=0;i<views.size();i++){String u=views.get(i).getUrl();s.append((u==null?savedUrls.get(i):u).replace("\n","")).append("\n");}getPreferences(0).edit().putString("tabs",s.toString()).putInt("active",active).apply();Toast.makeText(this,"Tab URL গুলো সেভ হয়েছে",Toast.LENGTH_SHORT).show();}
 @Override public void onBackPressed(){if(active>=0&&views.get(active).canGoBack())views.get(active).goBack();else new AlertDialog.Builder(this).setMessage("ACE67 BROWSER বন্ধ করবেন?").setPositiveButton("Exit",(d,w)->finish()).setNegativeButton("Stay",null).show();}
}